package com.collegeerp.erp.email.controller;import com.collegeerp.erp.common.api.ApiResponse;import com.collegeerp.erp.common.dto.PageResponse;import com.collegeerp.erp.email.dto.EmailNotificationResponse;import com.collegeerp.erp.email.enums.*;import com.collegeerp.erp.email.service.EmailAdminService;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/super-admin/email-notifications")public class EmailAdminController{private final EmailAdminService s;public EmailAdminController(EmailAdminService s){this.s=s;}@GetMapping public ApiResponse<PageResponse<EmailNotificationResponse>>search(@RequestParam(required=false)EmailStatus status,@RequestParam(required=false)EmailType emailType,@RequestParam(required=false)String recipientEmail,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="10")int size){return ApiResponse.success("Email notifications retrieved",s.search(status,emailType,recipientEmail,page,size));}@GetMapping("/{id}")public ApiResponse<EmailNotificationResponse>get(@PathVariable Long id){return ApiResponse.success("Email notification retrieved",s.get(id));}@PostMapping("/{id}/retry")public ApiResponse<EmailNotificationResponse>retry(@PathVariable Long id){return ApiResponse.success("Email queued for retry",s.retry(id));}@PostMapping("/{id}/cancel")public ApiResponse<EmailNotificationResponse>cancel(@PathVariable Long id){return ApiResponse.success("Email cancelled",s.cancel(id));}}
